-- State transitions declared for TimeoffRequest (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION timeoff.timeoff_requests_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('approved', 'cancelled'), ('pending', 'approved'), ('pending', 'cancelled'), ('pending', 'rejected'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: timeoff_requests.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS timeoff_requests_status_transition_check ON timeoff.timeoff_requests;
CREATE TRIGGER timeoff_requests_status_transition_check
    BEFORE UPDATE OF "status" ON timeoff.timeoff_requests
    FOR EACH ROW EXECUTE FUNCTION timeoff.timeoff_requests_status_transition_check();
